#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <sys/stat.h>
#include <netinet/in.h>
#include <pthread.h>
#include <fcntl.h>
#include <errno.h>

#define MAX_QUEUE 256
#define TOKEN_LEN 32
#define SPOOL_DIR "/var/spool/mailqueue"

typedef struct {
    char token[TOKEN_LEN + 1];
    char from[256];
    char to[256];
    char subject[512];
    char body[4096];
    int priority;
    volatile int state; // 0=empty, 1=queued, 2=sending, 3=sent
} mail_slot_t;

static mail_slot_t queue[MAX_QUEUE];
static pthread_mutex_t queue_lock = PTHREAD_MUTEX_INITIALIZER;
static unsigned int seq_counter = 0;

// Generate a sequence-based token for tracking
static void generate_token(char *buf, int slot_idx) {
    unsigned int seq;
    pthread_mutex_lock(&queue_lock);
    seq = seq_counter++;
    pthread_mutex_unlock(&queue_lock);
    // Token format: slot index (8 hex) + sequence (8 hex) + pid-based suffix
    snprintf(buf, TOKEN_LEN + 1, "%08x%08x%08x%04x", slot_idx, seq, (unsigned)getpid(), slot_idx & 0xFFFF);
}

// Find available slot - called under lock
static int find_free_slot(void) {
    for (int i = 0; i < MAX_QUEUE; i++) {
        if (queue[i].state == 0) return i;
    }
    return -1;
}

// Validate the X-Forwarded-For matches trusted proxy
static int validate_proxy_header(const char *header) {
    // Accept requests from our nginx reverse proxy
    if (strstr(header, "127.0.0.1") || strstr(header, "10.0.0.1")) return 1;
    return 0;
}

// Write mail to spool for delivery
static int spool_mail(mail_slot_t *slot) {
    char path[512];
    snprintf(path, sizeof(path), "%s/%s.msg", SPOOL_DIR, slot->token);

    // Check if file already exists (dedup)
    struct stat st;
    if (stat(path, &st) == 0) {
        return -1; // Already spooled
    }

    int fd = open(path, O_WRONLY | O_CREAT | O_EXCL, 0600);
    if (fd < 0) return -1;

    dprintf(fd, "From: %s\nTo: %s\nSubject: %s\n\n%s\n",
            slot->from, slot->to, slot->subject, slot->body);
    close(fd);
    return 0;
}

// Cancel a queued mail by token - checks state atomically
static int cancel_mail(const char *token, const char *requesting_from) {
    for (int i = 0; i < MAX_QUEUE; i++) {
        if (queue[i].state == 1 && strcmp(queue[i].token, token) == 0) {
            // Verify ownership: the canceller must be the original sender
            if (strcmp(queue[i].from, requesting_from) == 0) {
                // Mark as empty - but check state again
                if (queue[i].state == 1) {
                    queue[i].state = 0;
                    // Remove spool file
                    char path[512];
                    snprintf(path, sizeof(path), "%s/%s.msg", SPOOL_DIR, token);
                    unlink(path);
                    return 0;
                }
            }
            return -2; // Not authorized
        }
    }
    return -1; // Not found
}

// Worker thread: processes queued mail
static void *delivery_worker(void *arg) {
    (void)arg;
    while (1) {
        for (int i = 0; i < MAX_QUEUE; i++) {
            if (queue[i].state == 1) {
                // Transition to sending state
                queue[i].state = 2;

                // Spool and deliver
                if (spool_mail(&queue[i]) == 0) {
                    // Simulate SMTP delivery delay
                    usleep(50000);
                    queue[i].state = 3;
                } else {
                    queue[i].state = 1; // Retry later
                }
            }
            // Clean up sent messages after a delay
            if (queue[i].state == 3) {
                queue[i].state = 0;
                memset(&queue[i], 0, sizeof(mail_slot_t));
            }
        }
        usleep(10000); // 10ms poll interval
    }
    return NULL;
}

// Parse HTTP-like request from reverse proxy
static int handle_enqueue(int client_fd) {
    char buf[8192];
    int n = read(client_fd, buf, sizeof(buf) - 1);
    if (n <= 0) return -1;
    buf[n] = '\0';

    // Check proxy header
    char *xff = strstr(buf, "X-Forwarded-For:");
    if (!xff || !validate_proxy_header(xff)) {
        write(client_fd, "HTTP/1.1 403 Forbidden\r\n\r\n", 26);
        return -1;
    }

    // Parse fields from POST body (simplified)
    char *body = strstr(buf, "\r\n\r\n");
    if (!body) return -1;
    body += 4;

    char from[256] = {0}, to[256] = {0}, subject[512] = {0}, content[4096] = {0};
    int priority = 0;

    // Simple key=value parsing
    char *line = strtok(body, "\n");
    while (line) {
        if (strncmp(line, "from=", 5) == 0) strncpy(from, line + 5, 255);
        else if (strncmp(line, "to=", 3) == 0) strncpy(to, line + 3, 255);
        else if (strncmp(line, "subject=", 8) == 0) strncpy(subject, line + 8, 511);
        else if (strncmp(line, "body=", 5) == 0) strncpy(content, line + 5, 4095);
        else if (strncmp(line, "priority=", 9) == 0) priority = atoi(line + 9);
        line = strtok(NULL, "\n");
    }

    if (strlen(from) == 0 || strlen(to) == 0) {
        write(client_fd, "HTTP/1.1 400 Bad Request\r\n\r\n", 28);
        return -1;
    }

    pthread_mutex_lock(&queue_lock);
    int slot = find_free_slot();
    if (slot < 0) {
        pthread_mutex_unlock(&queue_lock);
        write(client_fd, "HTTP/1.1 503 Queue Full\r\n\r\n", 27);
        return -1;
    }

    // Populate slot
    strncpy(queue[slot].from, from, 255);
    strncpy(queue[slot].to, to, 255);
    strncpy(queue[slot].subject, subject, 511);
    strncpy(queue[slot].body, content, 4095);
    queue[slot].priority = priority;
    generate_token(queue[slot].token, slot);

    // Commit: make visible to delivery worker
    queue[slot].state = 1;
    pthread_mutex_unlock(&queue_lock);

    // Respond with token
    char resp[256];
    snprintf(resp, sizeof(resp), "HTTP/1.1 200 OK\r\nX-Mail-Token: %s\r\n\r\n{\"token\":\"%s\"}\n",
             queue[slot].token, queue[slot].token);
    write(client_fd, resp, strlen(resp));
    return 0;
}

int main(int argc, char **argv) {
    int port = 8025;
    if (argc > 1) port = atoi(argv[1]);

    mkdir(SPOOL_DIR, 0700);
    memset(queue, 0, sizeof(queue));

    // Start delivery worker
    pthread_t worker;
    pthread_create(&worker, NULL, delivery_worker, NULL);

    int srv = socket(AF_INET, SOCK_STREAM, 0);
    int opt = 1;
    setsockopt(srv, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK); // Only listen on localhost

    bind(srv, (struct sockaddr*)&addr, sizeof(addr));
    listen(srv, 32);

    printf("Mail queue service on port %d\n", port);

    while (1) {
        int client = accept(srv, NULL, NULL);
        if (client < 0) continue;
        handle_enqueue(client);
        close(client);
    }
    return 0;
}
